join public.kunthai_countries country on country.iso2 = v.country_iso
on conflict (code) do update set
  country_iso = excluded.country_iso,
  name = excluded.name,
  display_name = excluded.display_name,
  type_label = excluded.type_label,
  parent_code = excluded.parent_code,
  level = excluded.level,
  aliases = excluded.aliases,
  source = excluded.source,
  sort_order = excluded.sort_order
where (region.name, region.display_name, region.type_label, region.parent_code, region.level, region.aliases, region.source, region.sort_order)
  is distinct from (excluded.name, excluded.display_name, excluded.type_label, excluded.parent_code, excluded.level, excluded.aliases, excluded.source, excluded.sort_order);

-- Parents and ancestor paths (these areas are all top level, but the refresh
-- keeps path_ids filled in for the new rows).
select public.kunthai_refresh_region_paths();

-- What each territory calls its areas ("Parish", "Commune", "Village"…).
update public.kunthai_countries country
set subdivision_level = v.level,
    subdivision_label = v.label,
    subdivision_label_plural = v.plural
from (values
  ('AC', 1, 'Settlement', 'Settlements'),
  ('AI', 1, 'District', 'Districts'),
  ('AQ', 1, 'Area', 'Areas'),
  ('AS', 1, 'District', 'Districts'),
  ('AW', 1, 'District', 'Districts'),
  ('AX', 1, 'Municipality', 'Municipalities'),
  ('BL', 1, 'Quarter', 'Quarters'),
  ('BM', 1, 'Parish', 'Parishes'),
  ('BV', 1, 'Area', 'Areas'),
  ('CC', 1, 'Island', 'Islands'),
  ('CK', 1, 'Island', 'Islands'),
  ('CW', 1, 'District', 'Districts'),
  ('CX', 1, 'Settlement', 'Settlements'),
  ('EH', 1, 'Province', 'Provinces'),
  ('FK', 1, 'Area', 'Areas'),
  ('FO', 1, 'Region', 'Regions'),
  ('GF', 1, 'Commune', 'Communes'),
  ('GG', 1, 'Parish', 'Parishes'),
  ('GI', 1, 'Area', 'Areas'),
  ('GP', 1, 'Commune', 'Communes'),
  ('GS', 1, 'Area', 'Areas'),
  ('GU', 1, 'Village', 'Villages'),
  ('HM', 1, 'Island', 'Islands'),
  ('IM', 1, 'Parish or town', 'Parishes and towns'),
  ('IO', 1, 'Island', 'Islands'),
  ('JE', 1, 'Parish', 'Parishes'),
  ('KY', 1, 'District', 'Districts'),
  ('MF', 1, 'Quarter', 'Quarters'),
  ('MO', 1, 'Parish', 'Parishes'),
  ('MP', 1, 'Municipality', 'Municipalities'),
  ('MQ', 1, 'Commune', 'Communes'),
  ('MS', 1, 'Parish', 'Parishes'),
  ('NC', 1, 'Province', 'Provinces'),
  ('NF', 1, 'Area', 'Areas'),
  ('NU', 1, 'Village', 'Villages'),
  ('PF', 1, 'Division', 'Divisions'),
  ('PM', 1, 'Commune', 'Communes'),
  ('PN', 1, 'Island', 'Islands'),
  ('PR', 1, 'Municipality', 'Municipalities'),
  ('RE', 1, 'Commune', 'Communes'),
  ('SJ', 1, 'Settlement', 'Settlements'),
  ('SX', 1, 'District', 'Districts'),
  ('TA', 1, 'Settlement', 'Settlements'),
  ('TC', 1, 'District', 'Districts'),
  ('TF', 1, 'District', 'Districts'),
  ('TK', 1, 'Atoll', 'Atolls'),
  ('VA', 1, 'Area', 'Areas'),
  ('VG', 1, 'Island', 'Islands'),
  ('VI', 1, 'District', 'Districts'),
  ('YT', 1, 'Commune', 'Communes')
) as v(country_iso, level, label, plural)
where country.iso2 = v.country_iso
  and (country.subdivision_level, country.subdivision_label, country.subdivision_label_plural)
      is distinct from (v.level::smallint, v.label, v.plural);

-- Place existing accounts in these countries: their profile city is matched
-- against the new areas. kunthai_sync_account_region only reads the profile.
select count(public.kunthai_sync_account_region(users.id))
from auth.users users
where upper(btrim(coalesce(users.raw_user_meta_data->>'country_code', ''))) in ('AC', 'AI', 'AQ', 'AS', 'AW', 'AX', 'BL', 'BM', 'BV', 'CC', 'CK', 'CW', 'CX', 'EH', 'FK', 'FO', 'GF', 'GG', 'GI', 'GP', 'GS', 'GU', 'HM', 'IM', 'IO', 'JE', 'KY', 'MF', 'MO', 'MP', 'MQ', 'MS', 'NC', 'NF', 'NU', 'PF', 'PM', 'PN', 'PR', 'RE', 'SJ', 'SX', 'TA', 'TC', 'TF', 'TK', 'VA', 'VG', 'VI', 'YT');
